<?php use App\Core\Html as H; $old=$_SESSION['form_old'] ?? []; unset($_SESSION['form_old']); ?>
<section class="card mt-4" id="nova"><div class="card-body"><h2 class="h4">Nova recorrência</h2><p class="text-secondary">Cadastre compromissos que se repetem. Use “Processar recorrências” para gerar as pendências vencidas.</p>
<form method="post" action="<?= H::escape($basePath.'/recorrencias') ?>" class="row g-3"><?= H::fields($csrfToken) ?><div class="col-md-8"><label for="rec-name" class="form-label">Descrição</label><input id="rec-name" name="descricao" class="form-control" maxlength="160" required value="<?= H::escape($old['descricao'] ?? '') ?>"></div><div class="col-md-4"><label for="rec-value" class="form-label">Valor (R$)</label><input id="rec-value" name="valor" class="form-control" inputmode="decimal" required value="<?= H::escape($old['valor'] ?? '') ?>"></div>
<div class="col-md-6"><label for="rec-category" class="form-label">Categoria</label><select id="rec-category" name="subgrupo_id" class="form-select" required><option value="">Selecione</option><?php foreach($grupos as $g): if(!(int)$g['ativo']) continue; foreach($g['subgrupos'] as $s): if(!(int)$s['ativo']) continue; ?><option value="<?= (int)$s['id'] ?>" <?= (int)($old['subgrupo_id'] ?? 0)===(int)$s['id'] ? 'selected' : '' ?>><?= H::escape($g['nome'].' · '.$s['nome']) ?></option><?php endforeach; endforeach; ?></select></div><div class="col-md-6"><label for="rec-account" class="form-label">Conta (opcional)</label><select id="rec-account" name="conta_id" class="form-select"><option value="">A definir</option><?php foreach($contas as $a): ?><option value="<?= (int)$a['id'] ?>"><?= H::escape($a['nome']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-3"><label for="rec-frequency" class="form-label">Frequência</label><select id="rec-frequency" name="frequencia" class="form-select"><?php foreach(['mensal'=>'Mensal','semanal'=>'Semanal','diaria'=>'Diária','anual'=>'Anual'] as $key=>$name): ?><option value="<?= $key ?>"><?= $name ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label for="rec-interval" class="form-label">A cada quantos períodos?</label><input id="rec-interval" name="intervalo" type="number" min="1" max="120" class="form-control" required value="<?= H::escape($old['intervalo'] ?? 1) ?>"></div><div class="col-md-3"><label for="rec-start" class="form-label">Primeiro vencimento</label><input id="rec-start" name="data_inicio" type="date" class="form-control" required value="<?= H::escape($old['data_inicio'] ?? date('Y-m-d')) ?>"></div><div class="col-md-3"><label for="rec-duration" class="form-label">Duração</label><select id="rec-duration" name="tipo_duracao" class="form-select"><option value="indefinida">Até eu encerrar</option><option value="quantidade">Quantidade definida abaixo</option></select></div><div class="col-md-4"><label for="rec-count" class="form-label">Quantidade (se definida)</label><input id="rec-count" name="total_ocorrencias" type="number" min="1" max="1200" class="form-control"></div><div class="col-md-8"><label for="rec-notes" class="form-label">Observações</label><input id="rec-notes" name="observacao" class="form-control" maxlength="500"></div><div class="col-12"><button class="btn btn-uai-primary">Criar recorrência</button></div></form></div></section>
